import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 18 He often does this!","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 18 He often does this!","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 17 Always young","link":"/life/english/new-concept/book-2/unit-01/lesson-017"},"next":{"text":"第二册：实践与进步 · Lesson 19 Sold out","link":"/life/english/new-concept/book-2/unit-01/lesson-019"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 17 Always young","link":"/life/english/new-concept/book-2/unit-01/lesson-017"},"next":{"text":"第二册：实践与进步 · Lesson 19 Sold out","link":"/life/english/new-concept/book-2/unit-01/lesson-019"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-018.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-018.md"}'),s={name:"life/english/new-concept/book-2/unit-01/lesson-018.md"};function i(l,e,r,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-18-he-often-does-this" tabindex="-1">第二册：实践与进步 · Lesson 18 He often does this! <a class="header-anchor" href="#第二册-实践与进步-·-lesson-18-he-often-does-this" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 18 He often does this!&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>一只狗总把主人的袋子叼到意外的地方，寻找时才发现这是老习惯；练习 have 的不同功能。本课的语言观察是：has a habit 中 has 是实义动词“有”，疑问句通常借助 does；has hidden 中 has 是完成时助动词，疑问时直接提前。完成学习后，请描述一个宠物或家人的重复习惯，再讲一次例外。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>bag</td><td>/bæɡ/</td><td>n.</td><td>包</td><td>a travel bag</td></tr><tr><td>missing</td><td>/ˈmɪsɪŋ/</td><td>adj.</td><td>找不到的</td><td>a missing key</td></tr><tr><td>search</td><td>/sɜːtʃ/</td><td>v.</td><td>搜寻</td><td>search a room</td></tr><tr><td>dog</td><td>/dɒɡ/</td><td>n.</td><td>狗</td><td>a guide dog</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>look for — 寻找，侧重过程</li><li>find out — 查明信息，不等同于找见某个物品</li></ul><h2 id="语法讲解-一般现在时与习惯" tabindex="-1">语法讲解：一般现在时与习惯 <a class="header-anchor" href="#语法讲解-一般现在时与习惯" aria-label="Permalink to &quot;语法讲解：一般现在时与习惯&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：has a habit 中 has 是实义动词“有”，疑问句通常借助 does；has hidden 中 has 是完成时助动词，疑问时直接提前。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Our dog often hides my bag under the sofa.</p></blockquote><p>我们的狗经常把我的包藏在沙发下面。</p><p>often 放在实义动词 hides 前；my bag 是宾语，under the sofa 是地点，第三人称单数动词加 -s。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Does the dog hides 错误；does 出现后使用 hide。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 often 与 yesterday 的重音，朗读 hides 与 searched，区分词尾 /z/ 与 /t/。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Our dog often hides my bag under the sofa. Yesterday I searched the hallway first. I found the bag beside his blanket.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述一个宠物或家人的重复习惯，再讲一次例外。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：often 放在实义动词 hides 前；my bag 是宾语，under the sofa 是地点，第三人称单数动词加 -s。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Does the dog hides 错误；does 出现后使用 hide。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 hide 的形式：Our dog often ___ my bag.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> hides</p><p><strong>解析：</strong> dog 是单数第三人称主语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>昨天包最终在哪里找到？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Beside the dog&#39;s blanket.</p><p><strong>解析：</strong> 昨天的实际地点不同于 often 所描述的常见地点。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改为一般疑问句：The dog has a favourite blanket。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Does the dog have a favourite blanket?</p><p><strong>解析：</strong> has 表拥有，借助 does 后用 have。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般现在时与习惯。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-017">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-019">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(s,[["render",i]]);export{p as __pageData,b as default};
